using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using DessertKitchen.Domain;
using DessertKitchen.Infrastructure;
using Microsoft.Data.Sqlite;
using Xunit;
namespace DessertKitchen.Tests;

public class InventoryTests
{
    static string Id()=>Guid.NewGuid().ToString("N");
    static DateOnly Today=>AllergenRules.Today();
    static (Store Store,string Path) Kitchen(){var path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"dessert-inventory-tests",Id(),"test.db");var s=new Store(path);Seed.Run(s);return(s,path);}
    static PurchaseLine Line(string item="cream-cheese",decimal quantity=280,decimal price=3.25m,string unit="g",bool reviewed=true,DateOnly? useBy=null)=>new(item,1,quantity,unit,price,BatchReference:"TEST-LOT",DateReviewed:reviewed,DateEvidence:reviewed?"Illustrative acceptance test evidence":"",UseBy:useBy);
    static PurchaseInput Purchase(params PurchaseLine[] lines)=>new(Id(),"sample-supplier","home",Today,lines.ToList(),"TEST RECEIPT");
    static ProductionInput Production(string recipe="lemon-pot",decimal quantity=4)=>new(Id(),recipe,1,quantity,quantity,"home","home",Today,"TEST-BATCH",DateReviewed:true,DateEvidence:"Illustrative production date review");
    static decimal Balance(Store s,string lot,string location="home")=>s.StockMovements().Where(m=>m.LotId==lot&&m.LocationId==location).Sum(m=>m.Quantity);
    static List<StockBalance> Balances(Store s)=>JsonSerializer.SerializeToElement(s.InventoryState(),Store.Json).GetProperty("balances").Deserialize<List<StockBalance>>(Store.Json)!;
    static void Fill(Store s,ProductionInput p,decimal factor=1){foreach(var r in s.Requirements(p.RecipeId,p.Version,p.PlannedYield))s.Receive(Purchase(Line(r.ItemId,r.Quantity*factor,r.Quantity*.01m,r.Unit)));}

    [Fact] public void InventoryMigrationStartsEmptyAndSharesIngredientIdentity()
    {var(s,_)=Kitchen();Assert.Empty(s.StockLots());Assert.Empty(s.StockMovements());Assert.Single(s.Locations());Assert.Equal("testing",s.Locations()[0].Mode);var i=s.Get<Ingredient>("ingredient","cream-cheese");var lot=s.Receive(Purchase(Line()))[0];Assert.Equal(i.Id,lot.ItemId);Assert.Equal(17,s.All<Ingredient>("ingredient").Count);}
    [Theory][InlineData("g",500,500)][InlineData("kg",.5,500)]
    public void PurchaseConvertsMassAndRetainsActualCost(string unit,decimal quantity,decimal expected)
    {var(s,_)=Kitchen();var count=s.Prices().Count;var lot=s.Receive(Purchase(Line(quantity:quantity,unit:unit,price:5)))[0];Assert.Equal(expected,Balance(s,lot.Id));Assert.Equal(.01m,lot.UnitCost);Assert.Equal(count,s.Prices().Count);}
    [Fact] public void LitresCasesAndPackagedIndividualsConvertWithoutMassVolumeGuessing()
    {var(s,_)=Kitchen();var lots=s.Receive(Purchase(Line("cream",.5m,2,"l"),Line("pot",12,1,"each") with{Packs=2,PackLabel="case",PacksPerCase=4}));Assert.Equal(500,lots[0].InitialQuantity);Assert.Equal(96,lots[1].InitialQuantity);var before=s.StockMovements().Count;Assert.Throws<ValidationException>(()=>s.Receive(Purchase(Line(unit:"ml"))));Assert.Equal(before,s.StockMovements().Count);}
    [Theory][InlineData(true,true,10)][InlineData(true,false,12)][InlineData(false,true,12)][InlineData(false,false,14.4)]
    public void VatBasisDeterminesInventoryCost(bool inclusive,bool recovery,decimal expected)
    {var(s,_)=Kitchen();var lot=s.Receive(Purchase(Line(price:12) with{VatRate=20,PriceIncludesVat=inclusive,RecoverVat=recovery}))[0];Assert.NotNull(lot.UnitCost);Assert.InRange(lot.UnitCost.Value*280,expected-.00000000000000000001m,expected+.00000000000000000001m);}
    [Fact] public void ReceiptRetriesAreIdempotentAndMultiLineFailureRollsBack()
    {var(s,_)=Kitchen();var p=Purchase(Line());var lot=s.Receive(p)[0];Assert.Equal(JsonSerializer.Serialize(lot),JsonSerializer.Serialize(s.Receive(p)[0]));Assert.Single(s.StockMovements());Assert.Throws<ConflictException>(()=>s.Receive(p with{Notes="Different"}));Assert.Throws<ValidationException>(()=>s.Receive(Purchase(Line(),Line("missing"))));Assert.Single(s.StockLots());Assert.Single(s.StockOperations());}
    [Fact] public void PartialPacksAreConsumedAtActualFifoCostAndLaterQuotesDoNotRewriteHistory()
    {var(s,_)=Kitchen();var first=s.Receive(Purchase(Line(quantity:100,price:1)))[0];var second=s.Receive(Purchase(Line(quantity:300,price:6)))[0];var p=Production();foreach(var r in s.Requirements(p.RecipeId,1,4).Where(r=>r.ItemId!="cream-cheese"))s.Receive(Purchase(Line(r.ItemId,r.Quantity,1,r.Unit)));var result=s.Produce(p);var used=result.Allocations.Where(a=>a.Item=="Cream cheese").ToList();Assert.Equal(new[]{100m,200m},used.Select(a=>a.Quantity));Assert.Equal(5,used.Sum(a=>a.Cost));Assert.Equal(0,Balance(s,first.Id));Assert.Equal(100,Balance(s,second.Id));s.AddPrice(DomainTests.Cheese(99) with{IngredientId="cream-cheese",SupplierId="sample-supplier",EffectiveDate=Today});Assert.Equal(result.UnitCost,s.StockLots().Single(l=>l.Id==result.FinishedLotId).UnitCost);}
    [Fact] public void NestedScalingWasteAndActualYieldRemainSeparate()
    {var(s,_)=Kitchen();var p=Production(quantity:2);var rows=s.Requirements(p.RecipeId,1,2);Assert.Equal(60,rows.Single(r=>r.ItemId=="biscuits").Quantity);Assert.Equal(150,rows.Single(r=>r.ItemId=="cream-cheese").Quantity);Assert.Equal(2,rows.Single(r=>r.ItemId=="pot").Quantity);Assert.Equal(165,s.Requirements(p.RecipeId,1,2,extraWaste:10).Single(r=>r.ItemId=="cream-cheese").Quantity);Fill(s,p,2);var actual=rows.Select(r=>new ActualUsage(r.Key,r.Quantity*.9m)).ToList();Assert.Throws<ValidationException>(()=>s.Produce(p with{ActualUsage=actual,ActualYield=1}));var result=s.Produce(p with{ActualUsage=actual,ActualYield=1,LabourCost=2,OtherCost=1,Notes="Measured less material and one pot rejected during preparation"});Assert.Equal(result.MaterialCost+3,result.BatchCost);Assert.Equal(result.BatchCost,result.UnitCost);Assert.Equal(1,Balance(s,result.FinishedLotId!));Assert.Equal(135,result.Allocations.Single(a=>a.Item=="Cream cheese").Quantity);}
    [Fact] public void ShortageRollsBackAllEarlierDeductionsAndDoesNotCreateBatch()
    {var(s,_)=Kitchen();var p=Production();var lot=s.Receive(Purchase(Line("biscuits",1000,1)))[0];var before=s.StockMovements().Count;Assert.False(s.PreviewProduction(p).CanProduce);Assert.Throws<ValidationException>(()=>s.Produce(p));Assert.Equal(before,s.StockMovements().Count);Assert.Equal(1000,Balance(s,lot.Id));Assert.DoesNotContain(s.StockLots(),l=>l.Kind=="recipe");}
    [Fact] public void PreparedComponentIsUsedOnceInsteadOfItsOriginalIngredients()
    {var(s,_)=Kitchen();var baseInput=Production("cheesecake-base",4);Fill(s,baseInput);var prepared=s.Produce(baseInput);var p=Production() with{HeldRecipeIds=["cheesecake-base"]};var requirements=s.Requirements(p.RecipeId,1,4,p.HeldRecipeIds);Assert.DoesNotContain(requirements,r=>r.ItemId=="biscuits");foreach(var r in requirements.Where(r=>r.Kind=="ingredient"))s.Receive(Purchase(Line(r.ItemId,r.Quantity,1,r.Unit)));var before=s.StockMovements().Where(m=>s.StockLots().Any(l=>l.Id==m.LotId&&l.ItemId=="biscuits")).Count();var result=s.Produce(p);Assert.Equal(0,Balance(s,prepared.FinishedLotId!));Assert.Contains(result.Allocations,a=>a.LotId==prepared.FinishedLotId);Assert.Equal(before,s.StockMovements().Where(m=>s.StockLots().Any(l=>l.Id==m.LotId&&l.ItemId=="biscuits")).Count());}
    [Fact] public void SelectedHistoricalVersionPinsNestedRecipeVersion()
    {var(s,_)=Kitchen();var child=s.Get<Recipe>("recipe","cheesecake-base");var changed=child with{Revision=2,Lines=[new("ingredient","biscuits",300,"g")]};s.Save("recipe",child.Id,1,changed,new(changed,s.Calculate(changed),Store.Now(),s.Assess(changed)));Assert.Equal(120,s.Requirements("lemon-pot",1,4).Single(r=>r.ItemId=="biscuits").Quantity);Assert.Equal(1,s.Requirements("lemon-pot",1,4,["cheesecake-base"]).Single(r=>r.Kind=="recipe").Version);}
    [Fact] public void MadeToOrderAndRetryNeverInventOrDoubleDeductFinishedStock()
    {var(s,_)=Kitchen();var p=Production() with{Mode="made-to-order"};Fill(s,p);var first=s.Produce(p);var count=s.StockMovements().Count;var again=s.Produce(p);Assert.Equal(first.BatchCost,again.BatchCost);Assert.Equal(count,s.StockMovements().Count);Assert.Null(first.FinishedLotId);Assert.DoesNotContain(s.StockLots(),l=>l.Kind=="recipe");}
    [Fact] public void ExpiredAndUnreviewedLotsRemainPhysicalButAreUnavailableUntilReviewed()
    {var(s,_)=Kitchen();var lots=s.Receive(Purchase(Line(quantity:100,useBy:Today.AddDays(-1)),Line(quantity:100,reviewed:false),Line(quantity:100,useBy:Today.AddDays(1))));var b=Balances(s);Assert.Equal(300,b.Sum(x=>x.Quantity));Assert.Equal(100,b.Sum(x=>x.Usable));Assert.Contains(b,x=>x.Status=="Use-by approaching");Assert.Throws<ValidationException>(()=>s.StockAction("waste",new(Id(),lots[0].Id,"home",1,"quality-control-sample")));s.ReviewLot(new(Id(),lots[1].Id,Today.AddDays(2),true,"Checked supplier label"));Assert.Equal(200,Balances(s).Sum(x=>x.Usable));s.StockAction("waste",new(Id(),lots[0].Id,"home",100,"expired"));Assert.Equal(0,Balance(s,lots[0].Id));}
    [Fact] public void NegativeStockAndPoolTransfersAreBlockedButMatchedTransfersReconcile()
    {var(s,_)=Kitchen();var lot=s.Receive(Purchase(Line()))[0];Assert.Throws<ValidationException>(()=>s.StockAction("waste",new(Id(),lot.Id,"home",281,"spoiled")));var fridge=s.AddLocation(new("","Fridge"));var live=s.AddLocation(new("","Commercial","commercial"));Assert.Throws<ValidationException>(()=>s.StockAction("transfer",new(Id(),lot.Id,"home",100,"Move",DestinationId:live.Id)));s.StockAction("transfer",new(Id(),lot.Id,"home",100,"Move",DestinationId:fridge.Id));Assert.Equal(180,Balance(s,lot.Id));Assert.Equal(100,Balance(s,lot.Id,fridge.Id));Assert.Equal(lot.InitialQuantity,s.StockMovements().Where(m=>m.LotId==lot.Id).Sum(m=>m.Quantity));}
    [Fact] public void ReversalsAreImmutableIdempotentAndCannotRemoveConsumedStock()
    {var(s,_)=Kitchen();var p=Purchase(Line());var lot=s.Receive(p)[0];var waste=new StockActionInput(Id(),lot.Id,"home",1,"damaged");s.StockAction("waste",waste);Assert.Throws<ValidationException>(()=>s.ReverseStock(new(Id(),p.OperationId,"Wrong receipt")));var reverse=new ReverseInput(Id(),waste.OperationId,"Recorded against wrong lot");s.ReverseStock(reverse);s.ReverseStock(reverse);Assert.Equal(280,Balance(s,lot.Id));Assert.Throws<ValidationException>(()=>s.ReverseStock(new(Id(),waste.OperationId,"Again")));s.ReverseStock(new(Id(),p.OperationId,"Wrong receipt"));Assert.Equal(0,Balance(s,lot.Id));using var db=s.Open();foreach(var table in new[]{"inventory_operations","inventory_lots","inventory_movements"}){using var cmd=db.CreateCommand();cmd.CommandText=$"DELETE FROM {table}";Assert.Throws<SqliteException>(()=>cmd.ExecuteNonQuery());}}
    [Fact] public void PartialStocktakeExplainsDifferenceAndRefusesConcurrentMovements()
    {var(s,_)=Kitchen();var lots=s.Receive(Purchase(Line(),Line("cream",300,1.7m,"ml")));var snap=s.StartStocktake(new("home"));Assert.Throws<ValidationException>(()=>s.FinaliseStocktake(new(Id(),snap.Id,[new(lots[0].Id,270)])));var count=new StocktakeInput(Id(),snap.Id,[new(lots[0].Id,270,"10g spilled before count")]);s.FinaliseStocktake(count);s.FinaliseStocktake(count);Assert.Equal(270,Balance(s,lots[0].Id));Assert.Equal(300,Balance(s,lots[1].Id));var fresh=s.StartStocktake(new("home"));s.StockAction("waste",new(Id(),lots[1].Id,"home",1,"spoiled"));Assert.Throws<ConflictException>(()=>s.FinaliseStocktake(new(Id(),fresh.Id,[new(lots[0].Id,269,"Count"),new(lots[1].Id,290,"Count")])));Assert.Equal(270,Balance(s,lots[0].Id));Assert.Equal(299,Balance(s,lots[1].Id));}
    [Fact] public void ShoppingCombinesNestedPlansRoundsPacksAndDoesNotDeduct()
    {var(s,_)=Kitchen();s.Receive(Purchase(Line(quantity:100)));var input=new ShoppingInput("home",[new("lemon-pot",1,4),new("biscoff-pot",1,2)]);var row=s.Shopping(input).Single(r=>r.ItemId=="cream-cheese");Assert.Equal(450,row.Required);Assert.Equal(350,row.Shortfall);Assert.Equal(2,row.SuggestedPacks);Assert.Equal(560,row.PurchaseQuantity);var edited=s.Shopping(input with{PackOverrides=new(){[row.Key]=3}}).Single(r=>r.ItemId==row.ItemId);Assert.Equal(840,edited.PurchaseQuantity);Assert.Single(s.StockMovements());Assert.Contains("Cream cheese",s.ShoppingCsv(input));}
    [Fact] public void AllergenChangesFlagIngredientsAndProducedBatchesWithoutChangingSnapshot()
    {var(s,_)=Kitchen();var p=Production();Fill(s,p);var result=s.Produce(p);var lot=s.StockLots().Single(l=>l.Id==result.FinishedLotId);var before=JsonSerializer.Serialize(lot.AllergenSnapshot,Store.Json);var item=s.Get<Ingredient>("ingredient","cream-cheese");s.Save("ingredient",item.Id,item.Revision,item with{Revision=item.Revision+1,Allergens="Changed supplier declaration"});Assert.True(Balances(s).Single(b=>b.Lot.Id==lot.Id).AllergenReviewRequired);Assert.Equal(before,JsonSerializer.Serialize(s.StockLots().Single(l=>l.Id==lot.Id).AllergenSnapshot,Store.Json));}
    [Fact] public void IsolatedAcceptanceScenarioReconcilesAndSurvivesBackupRestore()
    {
        var(s,path)=Kitchen();var scenario=s.Get<Scenario>("scenario","baseline");var versions=s.Versions("lemon-pot");s.Receive(Purchase(Line(),Line("cream",300,1.70m,"ml"),Line("butter",250,1.85m)));
        var p=Production();foreach(var r in s.Requirements(p.RecipeId,1,4).Where(r=>r.ItemId is not "cream-cheese" and not "cream" and not "butter"))s.Receive(Purchase(Line(r.ItemId,r.Quantity*2,r.Quantity*.01m,r.Unit)));
        Assert.Equal(20,s.PreviewProduction(p).Requirements.Single(r=>r.Requirement.ItemId=="cream-cheese").Shortage);
        s.Receive(Purchase(Line()));var result=s.Produce(p);Assert.Equal(4,Balance(s,result.FinishedLotId!));Assert.Equal(300,result.Allocations.Where(a=>a.Item=="Cream cheese").Sum(a=>a.Quantity));Assert.Equal(160,result.Allocations.Where(a=>a.Item=="Double cream").Sum(a=>a.Quantity));
        s.StockAction("waste",new(Id(),result.FinishedLotId!,"home",1,"quality-control-sample","Isolated illustrative taste test"));Assert.Equal(3,Balance(s,result.FinishedLotId!));
        var snap=s.StartStocktake(new("home"));var butter=s.StockLots().First(l=>l.ItemId=="butter");s.FinaliseStocktake(new(Id(),snap.Id,[new(butter.Id,200,"2g handling loss found during physical count")]));Assert.Equal(200,Balance(s,butter.Id));
        var shopping=s.Shopping(new("home",[new("lemon-pot",1,4)]));Assert.Equal(40,shopping.Single(r=>r.ItemId=="cream-cheese").Shortfall);
        Assert.Equal(JsonSerializer.Serialize(scenario),JsonSerializer.Serialize(s.Get<Scenario>("scenario","baseline")));Assert.Equal(JsonSerializer.Serialize(versions),JsonSerializer.Serialize(s.Versions("lemon-pot")));
        File.WriteAllBytes(path+".backup",s.Backup());Store.Restore(path+".backup",path+".restored");var restored=new Store(path+".restored");Assert.Equal(JsonSerializer.Serialize(s.StockMovements()),JsonSerializer.Serialize(restored.StockMovements()));Assert.Equal(JsonSerializer.Serialize(s.StockOperations()),JsonSerializer.Serialize(restored.StockOperations()));Assert.Equal(3,Balance(restored,result.FinishedLotId!));
    }
    [Fact] public async Task AuthenticatedDraftConfirmationIsAtomicAndIdempotent()
    {
        using var factory=new KitchenFactory();using var c=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/inventory/state")).StatusCode);c.DefaultRequestHeaders.Add("X-Kitchen-Request","1");(await c.PostAsJsonAsync("/api/auth/setup",new{password="inventory-test-password"})).EnsureSuccessStatusCode();
        var s=new Store(factory.DatabasePath);var input=Purchase(Line());var response=await c.PostAsJsonAsync("/api/drafts/inventory-purchase/current",new DraftInput(0,JsonSerializer.SerializeToElement(input,Store.Json),Id()));response.EnsureSuccessStatusCode();var d=(await response.Content.ReadFromJsonAsync<WorkingDraft>())!;Assert.Empty(s.StockMovements());
        for(int i=0;i<2;i++)(await c.PostAsJsonAsync("/api/inventory/confirm/purchase/current",new{revision=d.Revision})).EnsureSuccessStatusCode();Assert.Single(s.StockMovements());Assert.NotNull(s.Draft("inventory-purchase","current")!.Result);
        var again=s.SaveDraft("inventory-purchase","current",new(d.Revision,JsonSerializer.SerializeToElement(input,Store.Json),Id()));(await c.PostAsJsonAsync("/api/inventory/confirm/purchase/current",new{revision=again.Revision})).EnsureSuccessStatusCode();Assert.Single(s.StockMovements());Assert.NotNull(s.Draft("inventory-purchase","current")!.Result);
    }
    [Fact] public void PopulatedV3MigrationPreservesEveryExistingRowAndCreatesAutomaticBackup()
    {
        var dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"dessert-migration-tests",Id());Directory.CreateDirectory(dir);var path=System.IO.Path.Combine(dir,"old.db");
        using(var db=new SqliteConnection("Data Source="+path)){db.Open();void Exec(string sql){using var cmd=db.CreateCommand();cmd.CommandText=sql;cmd.ExecuteNonQuery();}Exec("CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)");foreach(var file in Directory.GetFiles(System.IO.Path.Combine(AppContext.BaseDirectory,"Migrations"),"*.sql").Where(f=>int.Parse(System.IO.Path.GetFileName(f).Split('_')[0])<=3).Order()){Exec(File.ReadAllText(file));Exec($"INSERT INTO schema_migrations VALUES({int.Parse(System.IO.Path.GetFileName(file).Split('_')[0])},'before')");}var body=JsonSerializer.Serialize(new Supplier("preserved",7,"Actual owner supplier"),Store.Json).Replace("'","''");Exec($"INSERT INTO documents VALUES('supplier','preserved',7,'{body}')");Exec("INSERT INTO working_drafts VALUES('recipe','new',3,'{\"name\":\"Unfinished owner recipe\"}','owner-request','before',NULL)");}
        var s=new Store(path);Assert.Equal(7,s.Get<Supplier>("supplier","preserved").Revision);Assert.Equal("Actual owner supplier",s.Get<Supplier>("supplier","preserved").Name);Assert.Equal(3,s.Draft("recipe","new")!.Revision);Assert.Empty(s.StockLots());Assert.Single(Directory.GetFiles(System.IO.Path.Combine(dir,"backups"),"before-migration-4-*.db"));var twice=new Store(path);Assert.Single(twice.Locations());
    }
}
